 buildingCount(w,type){let n=0;for(const id of this.territory){const t=w.map.get(id);if(t)n+=t.buildings.filter(x=>x===type).length;}return n;}capacity(w){let n=0;for(const id of this.territory){const t=w.map.get(id);if(!t)continue;for(const b of t.buildings)n+=NS.BUILDINGS[b]?.capacity||0;}return n;}storageCaps(w){let f=120,wood=90,stone=80;for(const id of this.territory){const t=w.map.get(id);if(!t)continue;for(const b of t.buildings){const s=NS.BUILDINGS[b]?.storage||{};f+=s.food||0;wood+=s.wood||0;stone+=s.stone||0;}}return{food:f,wood,stone};}targetWood(w){return Math.min(this.storageCaps(w).wood*.76,48+this.territory.size*13+(this.expansionProject?22:0));}targetStone(w){return Math.min(this.storageCaps(w).stone*.74,34+this.territory.size*8+(this.expansionProject?11:0));}
 demographics(){const d={child:0,teen:0,adult:0,middle:0,elder:0,reproductiveWomen:0,reproductiveMen:0};for(const p of this.residents.filter(p=>p.alive)){if(p.age<=14)d.child++;else if(p.age<=17)d.teen++;else if(p.age<=42)d.adult++;else if(p.age<=64)d.middle++;else d.elder++;if(p.sex==='여'&&p.age>=18&&p.age<=40)d.reproductiveWomen++;if(p.sex==='남'&&p.age>=18&&p.age<=50)d.reproductiveMen++;}return d;}tileResidents(tileId){return this.residents.filter(p=>p.alive&&p.homeTileId===tileId);}occupiedTerritoryCount(w){let n=0;for(const id of this.territory)if(this.tileResidents(id).length>0)n++;return n;}
 resourceRatios(w){let cap={food:0,wood:0,stone:0,gold:0},cur={food:0,wood:0,stone:0,gold:0};for(const id of this.territory){const t=w.map.get(id);if(!t)continue;t.syncResources(w.ordinalDay());for(const k of Object.keys(cap)){cap[k]+=t.resourceCap[k]||0;cur[k]+=t.resources[k]||0;}}return{food:cap.food?cur.food/cap.food:0,wood:cap.wood?cur.wood/cap.wood:0,stone:cap.stone?cur.stone/cap.stone:0,gold:cap.gold?cur.gold/cap.gold:0};}
 securityScore(w){const guards=this.residents.filter(p=>p.job==='경비'&&p.assignment!=='PIONEER'),skill=guards.reduce((s,p)=>s+p.skills.combat,0)*.10,palisades=this.buildingCount(w,'palisade');return Math.round(skill+palisades*5+this.territory.size*.35);}availableSettlers(){return this.residents.filter(p=>p.alive&&p.age>=16&&p.age<=55&&p.assignment!=='PIONEER');}
 harvestMultiplier(kind,t){let m=1;if(kind==='food'&&this.hasTech('AGRICULTURE'))m*=1.08;if(kind==='food'&&t.hasBuilding('farmstead'))m*=1.10;if(kind==='wood'&&this.hasTech('CARPENTRY'))m*=1.12;if(kind==='stone'&&this.hasTech('MASONRY'))m*=1.10;return m;}
 knowledgeMultiplier(){let m=1;if(this.hasTech('RECORD_KEEPING'))m*=1.15;if(this.hasTech('SCHOLARSHIP'))m*=1.32;return m;}gainKnowledge(amount,w,source='생활'){if(this.status!=='active')return;const n=amount*this.knowledgeMultiplier();this.totalKnowledge+=n;this.knowledgeBySource[source]=(this.knowledgeBySource[source]||0)+n;if(!this.researchTarget)this.selectResearch(w,false);if(!this.researchTarget)return;this.researchProgress+=n;const tech=NS.TECH[this.researchTarget];if(this.researchProgress>=tech.cost){this.researchProgress-=tech.cost;this.technologies.add(tech.id);const done=tech.id;this.researchTarget=null;w.log(`${this.name}이(가) 기술 「${tech.label}」 연구를 완료했습니다.`,true,'TECH_COMPLETED',{village:this.name,techId:done,tech:tech.label,totalKnowledge:+this.totalKnowledge.toFixed(1)});this.selectResearch(w,true);}}
 selectResearch(w,announce=true){if(this.researchTarget||this.technologies.size>=NS.TECH_ORDER.length)return;const id=NS.TechSystem.choose(this,w);if(!id)return;this.researchTarget=id;if(announce)w.log(`${this.name}이(가) 「${NS.TECH[id].label}」 연구를 시작했습니다.`,false,'TECH_STARTED',{village:this.name,techId:id,tech:NS.TECH[id].label,cost:NS.TECH[id].cost});}
 maintenanceGold(w){let m=0;for(const id of this.territory){const t=w.map.get(id);if(!t)continue;for(const b of t.buildings)m+=NS.BUILDINGS[b]?.maint||0;}return m;}
 dailyTick(w){if(this.status!=='active')return;if(!this.researchTarget)this.selectResearch(w,false);for(const p of this.residents.filter(p=>p.alive))p.act(this,w);const caps=this.storageCaps(w);if(this.food>caps.food)this.food-=Math.max(.2,(this.food-caps.food)*.08);this.food=Math.min(this.food,caps.food*1.10);this.wood=Math.min(this.wood,caps.wood*1.04);this.stone=Math.min(this.stone,caps.stone*1.04);const working=this.residents.filter(p=>p.alive&&p.age>=16&&p.assignment!=='PIONEER'&&(w.ordinalDay()-(p.lastMoveDay||-9999)>180)).length,merchants=this.residents.filter(p=>p.alive&&p.job==='상인'&&p.assignment!=='PIONEER').length;this.gold+=working*.0014+merchants*.0018+(this.hasTech('MARKET')?merchants*.0008:0);const maint=this.maintenanceGold(w);if(this.gold>=maint)this.gold-=maint;else{this.gold=0;for(const p of this.residents)p.happiness=Math.max(0,p.happiness-.004);}this.threat=Math.max(0,this.threat-.12);this.progressExpansion(w);}
 maintainSettlements(w){for(const id of [...this.territory]){if(id===this.coreTileId)continue;const t=w.map.get(id),here=this.tileResidents(id);if(here.length){t.unoccupiedDays=0;continue;}const donors=this.availableSettlers().filter(p=>p.homeTileId!==id&&this.tileResidents(p.homeTileId).length>1);if(donors.length){const p=donors.sort((a,b)=>this.tileResidents(b.homeTileId).length-this.tileResidents(a.homeTileId).length)[0];p.homeTileId=id;t.unoccupiedDays=0;w.log(`${this.name}의 ${p.name}이(가) 빈 정착지로 이동해 거점을 유지합니다.`,false,'SETTLEMENT_REPOPULATED',{village:this.name,tileId:id,person:p.name});}else{this.territory.delete(id);t.ownerId=null;t.buildings=[];t.unoccupiedDays=0;w.log(`${this.name}은 정착민을 유지할 수 없어 (${t.x},${t.y}) 거점을 포기했습니다.`,true,'OUTPOST_ABANDONED',{village:this.name,tileId:id});}}this.pruneDisconnectedTerritory(w);}
 pruneDisconnectedTerritory(w){if(!this.territory.has(this.coreTileId))return;const seen=new Set([this.coreTileId]),q=[this.coreTileId];while(q.length){const id=q.shift();for(const n of w.map.neighbors4(id))if(this.territory.has(n.id)&&!seen.has(n.id)){seen.add(n.id);q.push(n.id);}}const cut=[...this.territory].filter(id=>!seen.has(id));if(!cut.length)return;for(const id of cut){this.territory.delete(id);const t=w.map.get(id);if(t){t.ownerId=null;t.buildings=[];}for(const p of this.residents)if(p.homeTileId===id)p.homeTileId=this.coreTileId;}w.log(`${this.name}의 연결이 끊긴 외곽 영토 ${cut.length}타일이 중립지대로 돌아갔습니다.`,true,'TERRITORY_DISCONNECTED',{village:this.name,tileIds:cut});}
